import{_ as t,o as r,c as l,ah as a}from"./chunks/framework.DjU4PSOm.js";const c=JSON.parse('{"title":"최종발표 문제 정의 근거 자료","description":"","frontmatter":{"tags":["computer/project"],"date":"2026-11-28T00:00:00.000Z"},"headers":[{"level":2,"title":"1. 발표에 쓴 사례","slug":"_1-발표에-쓴-사례","link":"#_1-발표에-쓴-사례","children":[{"level":3,"title":"1-1. 일본: \\"피난 권고\\"를 헷갈려서 그 말을 없앴다","slug":"_1-1-일본-피난-권고-를-헷갈려서-그-말을-없앴다","link":"#_1-1-일본-피난-권고-를-헷갈려서-그-말을-없앴다","children":[{"level":4,"title":"한국에도 맞는 이유","slug":"한국에도-맞는-이유","link":"#한국에도-맞는-이유","children":[]}]},{"level":3,"title":"1-2. 일본: 재난 때 아이가 어디 있는지 모르면 보호자 95.1%가 불안하다","slug":"_1-2-일본-재난-때-아이가-어디-있는지-모르면-보호자-95-1-가-불안하다","link":"#_1-2-일본-재난-때-아이가-어디-있는지-모르면-보호자-95-1-가-불안하다","children":[{"level":4,"title":"한국에도 맞는 이유: 아이가 혼자 있는 시간이 많다","slug":"한국에도-맞는-이유-아이가-혼자-있는-시간이-많다","link":"#한국에도-맞는-이유-아이가-혼자-있는-시간이-많다","children":[]}]}]},{"level":2,"title":"2. 예비 자료: 아이가 재난 때 제대로 대처하지 못한 설문","slug":"_2-예비-자료-아이가-재난-때-제대로-대처하지-못한-설문","link":"#_2-예비-자료-아이가-재난-때-제대로-대처하지-못한-설문","children":[{"level":3,"title":"2-1. 초등학생 241명 지진해일 설문 (초록우산 어린이재단, 2011)","slug":"_2-1-초등학생-241명-지진해일-설문-초록우산-어린이재단-2011","link":"#_2-1-초등학생-241명-지진해일-설문-초록우산-어린이재단-2011","children":[]},{"level":3,"title":"2-2. 만 7세 이하 어린이 44명 안전 설문 (서울신문, 초록우산어린이재단, 2020)","slug":"_2-2-만-7세-이하-어린이-44명-안전-설문-서울신문-초록우산어린이재단-2020","link":"#_2-2-만-7세-이하-어린이-44명-안전-설문-서울신문-초록우산어린이재단-2020","children":[]},{"level":3,"title":"2-3. 2016년 경주 지진(규모 5.8) 때 대피하지 않은 학교","slug":"_2-3-2016년-경주-지진-규모-5-8-때-대피하지-않은-학교","link":"#_2-3-2016년-경주-지진-규모-5-8-때-대피하지-않은-학교","children":[]},{"level":3,"title":"2-4. [확인 필요] 2026년 국민 안전 실태조사 기사","slug":"_2-4-확인-필요-2026년-국민-안전-실태조사-기사","link":"#_2-4-확인-필요-2026년-국민-안전-실태조사-기사","children":[]}]},{"level":2,"title":"3. 예비 자료: 재난문자 말이 어렵다 (한국)","slug":"_3-예비-자료-재난문자-말이-어렵다-한국","link":"#_3-예비-자료-재난문자-말이-어렵다-한국","children":[]},{"level":2,"title":"4. 예비 자료: 2023-05-31 서울 경계경보 (뭘 해야 할지 몰랐다)","slug":"_4-예비-자료-2023-05-31-서울-경계경보-뭘-해야-할지-몰랐다","link":"#_4-예비-자료-2023-05-31-서울-경계경보-뭘-해야-할지-몰랐다","children":[]},{"level":2,"title":"5. 예비 자료: 부모와 떨어진 아이","slug":"_5-예비-자료-부모와-떨어진-아이","link":"#_5-예비-자료-부모와-떨어진-아이","children":[]}],"relativePath":"computer/project/AWS-PBL/03. 최종발표 문제 정의 근거 (2026-11-28).md","filePath":"computer/project/AWS-PBL/03. 최종발표 문제 정의 근거 (2026-11-28).md"}'),i={name:"computer/project/AWS-PBL/03. 최종발표 문제 정의 근거 (2026-11-28).md"};function o(n,e,s,h,u,w){return r(),l("div",null,[...e[0]||(e[0]=[a('<h1 id="최종발표-문제-정의-근거-자료" tabindex="-1">최종발표 문제 정의 근거 자료 <a class="header-anchor" href="#최종발표-문제-정의-근거-자료" aria-label="Permalink to &quot;최종발표 문제 정의 근거 자료&quot;">​</a></h1><blockquote><p>AWS Career Launchpad PBL 또리(DDORI) 최종발표(2026-11-28) &quot;01 문제 정의&quot;에 쓴 사례와 통계. 숫자는 원문을 직접 열어 확인한 것만 적었고, 덜 확인된 것은 따로 표시했다.</p></blockquote><p>발표에는 두 가지만 썼다.</p><ol><li><strong>말이 어려워서 제대로 대처하지 못한다:</strong> 일본 &quot;피난 권고 / 피난 지시&quot; 사례 (4쪽)</li><li><strong>재난 때 아이와 떨어진 부모는 불안하다:</strong> 일본 보호자 95.1% (5쪽 &quot;3. 연결&quot; 칸)</li></ol><p>나머지는 Q&amp;A와 다음에 쓸 때를 위한 예비 자료다.</p><hr><h2 id="_1-발표에-쓴-사례" tabindex="-1">1. 발표에 쓴 사례 <a class="header-anchor" href="#_1-발표에-쓴-사례" aria-label="Permalink to &quot;1. 발표에 쓴 사례&quot;">​</a></h2><h3 id="_1-1-일본-피난-권고-를-헷갈려서-그-말을-없앴다" tabindex="-1">1-1. 일본: &quot;피난 권고&quot;를 헷갈려서 그 말을 없앴다 <a class="header-anchor" href="#_1-1-일본-피난-권고-를-헷갈려서-그-말을-없앴다" aria-label="Permalink to &quot;1-1. 일본: &quot;피난 권고&quot;를 헷갈려서 그 말을 없앴다&quot;">​</a></h3><ul><li>2019년 태풍 19호(하기비스) 때 피난 권고가 나와도 대피하지 않거나 늦게 대피한 사람이 많았다.</li><li>일본 내각부 주민 웹 설문: 태풍 19호로 인명 피해가 난 시정촌의 웹 모니터 3,078명, 2020년 1월</li><li>&quot;피난 권고(避難勧告)&quot;와 &quot;피난 지시(避難指示, 緊急)&quot;의 뜻을 바르게 알았는지</li></ul><table tabindex="0"><thead><tr><th>응답</th><th>비율</th></tr></thead><tbody><tr><td>둘 다 바르게 알았다</td><td><strong>17.7%</strong> (545명)</td></tr><tr><td>피난 권고만 바르게 알았다</td><td>9.1% (280명)</td></tr><tr><td>피난 지시만 바르게 알았다</td><td>6.8% (209명)</td></tr><tr><td>둘 다 틀렸다</td><td><strong>66.4%</strong> (2,044명)</td></tr></tbody></table><ul><li>&quot;실제로 언제 대피하겠냐&quot;는 질문: 피난 <strong>지시</strong> 때 대피 40.0%(가장 많음), 대피를 시작해야 하는 피난 <strong>권고</strong> 때 대피 26.4%</li><li>결과: 2021-05-20 재해대책기본법 개정으로 &quot;피난 권고&quot; 단계를 없애고 &quot;피난 지시&quot; 하나로 합쳤다. 재난문자(긴급속보 메일)뿐 아니라 방송 등 어디서도 &quot;피난 권고&quot;가 나오지 않는다.</li><li>출처 <ul><li>내각부 「令和元年台風第19号等を踏まえた避難情報及び広域避難等のあり方について（最終とりまとめ）」(2020-12-24), 13~14쪽: <a href="https://www.bousai.go.jp/pdf/201224_kouiki.pdf" target="_blank" rel="noreferrer">https://www.bousai.go.jp/pdf/201224_kouiki.pdf</a></li><li>내각부 워킹그룹 제2회 자료(주민 설문 결과), 11쪽: <a href="https://www.bousai.go.jp/fusuigai/typhoonworking/pdf/dai2kai/siryo5.pdf" target="_blank" rel="noreferrer">https://www.bousai.go.jp/fusuigai/typhoonworking/pdf/dai2kai/siryo5.pdf</a></li><li>내각부 개요: <a href="https://www.bousai.go.jp/fusuigai/subtyphoonworking/pdf/chukan/gaiyo.pdf" target="_blank" rel="noreferrer">https://www.bousai.go.jp/fusuigai/subtyphoonworking/pdf/chukan/gaiyo.pdf</a></li><li>웨더뉴스, 피난 권고 폐지 시행(2021-05): <a href="https://weathernews.jp/s/topics/202105/170155/" target="_blank" rel="noreferrer">https://weathernews.jp/s/topics/202105/170155/</a></li></ul></li></ul><h4 id="한국에도-맞는-이유" tabindex="-1">한국에도 맞는 이유 <a class="header-anchor" href="#한국에도-맞는-이유" aria-label="Permalink to &quot;한국에도 맞는 이유&quot;">​</a></h4><ul><li>한국 재난문자 표준 문안도 권고와 명령을 나눈다. 산불 대피 <strong>권고</strong> &quot;대피하시기 바랍니다&quot;, 산불 대피 <strong>명령</strong> &quot;반드시 대피해주시기 바랍니다&quot;. <ul><li>행정안전부 「재난문자방송 기준 및 운영규정」 [별표 2] 표준문안: <a href="https://www.law.go.kr/flDownload.do?bylClsCd=200201&amp;flSeq=149749973" target="_blank" rel="noreferrer">https://www.law.go.kr/flDownload.do?bylClsCd=200201&amp;flSeq=149749973</a></li></ul></li><li>대피 명령은 「재난 및 안전관리 기본법」 제40조가 근거이고, 따르지 않으면 과태료(200만 원 이하)와 강제 대피가 있다. 대피 권고는 강제력이 없는 안내 단계다. <ul><li>설명 글: <a href="https://lawscool.co.kr/entry/%EC%9E%AC%EB%82%9C-%EC%8B%9C-%EC%A3%BC%EB%AF%BC%EB%8C%80%ED%94%BC%EC%99%80-%EC%9E%AC%EB%82%9C%EB%AC%B8%EC%9E%90%EC%97%90-%EB%8C%80%ED%95%98%EC%97%AC" target="_blank" rel="noreferrer">https://lawscool.co.kr/entry/재난-시-주민대피와-재난문자에-대하여</a></li><li>주의: 법 조문 원문은 국가법령정보센터에서 직접 확인하지 않았다.</li></ul></li><li>정부도 2025년 8월, &quot;안전한 곳으로 대피&quot;처럼 모호한 문자를 언제, 어디로, 어떻게 대피할지 담게 고치기로 했다. 경향신문: <a href="https://www.khan.co.kr/article/202508272014015" target="_blank" rel="noreferrer">https://www.khan.co.kr/article/202508272014015</a></li><li>2023년 예천 산사태 때는 산사태가 시작된 뒤에야 대피 문자가 갔고, 강제 대피 명령은 스무 시간 가까이 지나 내려졌다. 이후 산사태 경보가 나면 바로 강제 대피 명령을 내리기로 했다. MBC: <a href="https://imnews.imbc.com/replay/2023/nwdesk/article/6505067_36199.html" target="_blank" rel="noreferrer">https://imnews.imbc.com/replay/2023/nwdesk/article/6505067_36199.html</a></li></ul><h3 id="_1-2-일본-재난-때-아이가-어디-있는지-모르면-보호자-95-1-가-불안하다" tabindex="-1">1-2. 일본: 재난 때 아이가 어디 있는지 모르면 보호자 95.1%가 불안하다 <a class="header-anchor" href="#_1-2-일본-재난-때-아이가-어디-있는지-모르면-보호자-95-1-가-불안하다" aria-label="Permalink to &quot;1-2. 일본: 재난 때 아이가 어디 있는지 모르면 보호자 95.1%가 불안하다&quot;">​</a></h3><ul><li>조사: 明光義塾(메이코 기주쿠), 2026-09-25 ~ 10-02, 인터넷 조사, 초1~고3 자녀를 둔 전국 보호자 1,000명, 2026-10-26 발표</li><li>재난 때 아이가 어디 있는지 모르는 상황에 불안하다 <strong>95.1%</strong> (매우 불안 61.4%, 조금 불안 33.7%)</li><li>보호자가 없을 때 재난이 나면 아이 혼자 안전을 지키기 어렵다 <strong>44.5%</strong> (못 할 것 같다 12.2%, 별로 못 할 것 같다 32.3%)</li><li>스마트폰 위치 정보를 쓰고 있다 35.6%</li><li>출처: PR TIMES 「子どもがいる家庭の防災に関する実態調査」: <a href="https://prtimes.jp/main/html/rd/p/000000338.000071552.html" target="_blank" rel="noreferrer">https://prtimes.jp/main/html/rd/p/000000338.000071552.html</a></li></ul><h4 id="한국에도-맞는-이유-아이가-혼자-있는-시간이-많다" tabindex="-1">한국에도 맞는 이유: 아이가 혼자 있는 시간이 많다 <a class="header-anchor" href="#한국에도-맞는-이유-아이가-혼자-있는-시간이-많다" aria-label="Permalink to &quot;한국에도 맞는 이유: 아이가 혼자 있는 시간이 많다&quot;">​</a></h4><ul><li>평일 방과후에 혼자 있는 6~17세 아이 약 <strong>116만 5천 명</strong>, 전체의 20% 이상 (홍나미, 정익중 2019 분석을 인용한 논문) <ul><li>한국보건사회연구원 「보건사회연구」 41권 2호: <a href="https://www.kihasa.re.kr/hswr/v.41/2/178/%EC%B4%88%EB%93%B1+%EB%B0%A9%EA%B3%BC%ED%9B%84%EB%8F%8C%EB%B4%84%EC%84%9C%EB%B9%84%EC%8A%A4+%EC%9D%B4%EC%9A%A9+%EC%9C%A0%ED%98%95%EC%9D%B4+%EB%8F%8C%EB%B4%84+%EA%B3%B5%EB%B0%B1%EC%97%90+%EB%AF%B8%EC%B9%98%EB%8A%94+%EC%98%81%ED%96%A5?view=pubreader" target="_blank" rel="noreferrer">https://www.kihasa.re.kr/hswr/v.41/2/178/초등+방과후돌봄서비스+이용+유형이+돌봄+공백에+미치는+영향?view=pubreader</a></li></ul></li><li>2020년 초등학생 학부모 5,050명 중 <strong>23.1%</strong>가 방과후 돌봄이 필요한데 받지 못한다. 맞벌이 가정은 17시 전후에 아이 혼자 있는 비율이 높다. <ul><li>한국보건사회연구원 보도자료 &quot;방과후돌봄 공백 여전&quot;(2021-06-09): <a href="https://www.kihasa.re.kr/news/press/view?seq=36809" target="_blank" rel="noreferrer">https://www.kihasa.re.kr/news/press/view?seq=36809</a></li></ul></li></ul><hr><h2 id="_2-예비-자료-아이가-재난-때-제대로-대처하지-못한-설문" tabindex="-1">2. 예비 자료: 아이가 재난 때 제대로 대처하지 못한 설문 <a class="header-anchor" href="#_2-예비-자료-아이가-재난-때-제대로-대처하지-못한-설문" aria-label="Permalink to &quot;2. 예비 자료: 아이가 재난 때 제대로 대처하지 못한 설문&quot;">​</a></h2><h3 id="_2-1-초등학생-241명-지진해일-설문-초록우산-어린이재단-2011" tabindex="-1">2-1. 초등학생 241명 지진해일 설문 (초록우산 어린이재단, 2011) <a class="header-anchor" href="#_2-1-초등학생-241명-지진해일-설문-초록우산-어린이재단-2011" aria-label="Permalink to &quot;2-1. 초등학생 241명 지진해일 설문 (초록우산 어린이재단, 2011)&quot;">​</a></h3><ul><li>헤럴드경제, &quot;초등생 안전교육 문제없나...지진해일 때 가장 안전한 곳은&quot;, 2011-03-29: <a href="https://mbiz.heraldcorp.com/article/10065794" target="_blank" rel="noreferrer">https://mbiz.heraldcorp.com/article/10065794</a></li><li>국내 한 초등학교 학생 241명 (일본 대지진 직후)</li><li>집 근처에 지진해일이 오면 가장 먼저 할 행동: 책상 아래로 숨겠다 65.6% (158명), 건물 밖으로 대피 12.9% (31명). 지진 흔들림 때 요령을 지진해일에 그대로 답했다.</li><li>가장 안전한 곳: 산 28.6%, 고층건물 옥상 25.7%</li><li>지진 교육을 받은 적 없음 15.6%</li><li>주의: 오래된 자료, 학교 한 곳</li></ul><h3 id="_2-2-만-7세-이하-어린이-44명-안전-설문-서울신문-초록우산어린이재단-2020" tabindex="-1">2-2. 만 7세 이하 어린이 44명 안전 설문 (서울신문, 초록우산어린이재단, 2020) <a class="header-anchor" href="#_2-2-만-7세-이하-어린이-44명-안전-설문-서울신문-초록우산어린이재단-2020" aria-label="Permalink to &quot;2-2. 만 7세 이하 어린이 44명 안전 설문 (서울신문, 초록우산어린이재단, 2020)&quot;">​</a></h3><ul><li>&quot;[우리 아이 마음 읽기] &#39;엄마 아빠와 떨어져 있을 때 가장 위험해요&#39;&quot;, 2020-05-18: <a href="https://go.seoul.co.kr/news/newsView.php?id=20200518016003&amp;section=society&amp;section2=&amp;page=7829" target="_blank" rel="noreferrer">https://go.seoul.co.kr/news/newsView.php?id=20200518016003&amp;section=society&amp;section2=&amp;page=7829</a></li><li>불이 났을 때: 119에 신고 50%, 크게 소리 지르기 29.5%, 밖으로 나오기 11.4%</li><li>길을 잃었을 때: 그 자리에 가만히 서 있기 45.5%, 경찰서 31.8%, 주위 어른에게 도움 18.2%</li><li>주의: 미취학 아동, 표본 44명</li></ul><h3 id="_2-3-2016년-경주-지진-규모-5-8-때-대피하지-않은-학교" tabindex="-1">2-3. 2016년 경주 지진(규모 5.8) 때 대피하지 않은 학교 <a class="header-anchor" href="#_2-3-2016년-경주-지진-규모-5-8-때-대피하지-않은-학교" aria-label="Permalink to &quot;2-3. 2016년 경주 지진(규모 5.8) 때 대피하지 않은 학교&quot;">​</a></h3><ul><li>서울신문, &quot;강진에도 &#39;가만히 자습하라&#39;는 학교들…&#39;제2의 세월호&#39;&quot;, 2016-09-13: <a href="https://www.seoul.co.kr/news/society/accident/2016/09/13/20160913500077" target="_blank" rel="noreferrer">https://www.seoul.co.kr/news/society/accident/2016/09/13/20160913500077</a></li><li>국회 자료를 인용한 논문: 야간자율학습 중이던 경북 88개 학교 중 42개 학교가 대피 조치를 하지 않았다. <a href="https://www.j-kosham.or.kr/journal/view.php?doi=10.9798%2FKOSHAM.2018.18.4.57" target="_blank" rel="noreferrer">https://www.j-kosham.or.kr/journal/view.php?doi=10.9798%2FKOSHAM.2018.18.4.57</a> (국회 원자료는 확인 못 함)</li></ul><h3 id="_2-4-확인-필요-2026년-국민-안전-실태조사-기사" tabindex="-1">2-4. [확인 필요] 2026년 국민 안전 실태조사 기사 <a class="header-anchor" href="#_2-4-확인-필요-2026년-국민-안전-실태조사-기사" aria-label="Permalink to &quot;2-4. [확인 필요] 2026년 국민 안전 실태조사 기사&quot;">​</a></h3><ul><li>아시아투데이, CBS (네이트 뉴스), 2026-05-03: <a href="https://news.nate.com/view/20260503n06092" target="_blank" rel="noreferrer">https://news.nate.com/view/20260503n06092</a> , <a href="https://m.news.nate.com/view/20260503n06203" target="_blank" rel="noreferrer">https://m.news.nate.com/view/20260503n06203</a></li><li>풍수해 대처법을 안다 37.4%, 지진 30.8%, 인파사고 17.4%, 위험정보를 가족이나 지인에게서 얻는다 73.9%</li><li>주의: 페이지 글자가 깨져서 조사 이름, 대상이 어린이인지 확인하지 못했다.</li></ul><hr><h2 id="_3-예비-자료-재난문자-말이-어렵다-한국" tabindex="-1">3. 예비 자료: 재난문자 말이 어렵다 (한국) <a class="header-anchor" href="#_3-예비-자료-재난문자-말이-어렵다-한국" aria-label="Permalink to &quot;3. 예비 자료: 재난문자 말이 어렵다 (한국)&quot;">​</a></h2><ul><li><strong>장소를 콕 집어 주면 더 많이 대피했다:</strong> 국립재난안전연구원이 산불 재난문자를 분석했더니 &quot;대피장소&quot; 대신 &quot;동해체육관&quot;처럼 쓸 때 대피 이동이 더 많았다. 숫자는 없음. MBC, 2023-08-07: <a href="https://imnews.imbc.com/replay/2023/nwdesk/article/6511939_36199.html" target="_blank" rel="noreferrer">https://imnews.imbc.com/replay/2023/nwdesk/article/6511939_36199.html</a></li><li><strong>농인 인터뷰:</strong> &quot;&#39;범람 우려&#39;, &#39;제설 요망&#39;, &#39;산사태 취약지역&#39;, &#39;금일 야간&#39;과 같은 표현은 직관적인 대피 행동으로 이어지기 힘들다&quot;. 7명 인터뷰. 뉴스핌, 2026-08-12: <a href="https://www.newspim.com/news/view/20260811001012" target="_blank" rel="noreferrer">https://www.newspim.com/news/view/20260811001012</a></li><li><strong>북한이탈주민 연구(2018):</strong> CBS 재난문자 표준 문안 28개로 이해도를 쟀더니 한자어와 외래어를 특히 어려워했다. <a href="https://scholar.kyobobook.co.kr/article/detail/4010026183924" target="_blank" rel="noreferrer">https://scholar.kyobobook.co.kr/article/detail/4010026183924</a></li></ul><hr><h2 id="_4-예비-자료-2023-05-31-서울-경계경보-뭘-해야-할지-몰랐다" tabindex="-1">4. 예비 자료: 2023-05-31 서울 경계경보 (뭘 해야 할지 몰랐다) <a class="header-anchor" href="#_4-예비-자료-2023-05-31-서울-경계경보-뭘-해야-할지-몰랐다" aria-label="Permalink to &quot;4. 예비 자료: 2023-05-31 서울 경계경보 (뭘 해야 할지 몰랐다)&quot;">​</a></h2><ul><li>오전 6시 32분 서울 경계경보 발령, 6시 41분쯤 &quot;대피할 준비를 하시고, 어린이와 노약자가 우선 대피할 수 있도록&quot; 문자. 왜, 어디로 대피하는지가 없었다. (문자 전문은 기사에 일부만 나와 원문 확인 필요)</li><li>약 20분 뒤 행정안전부가 &quot;오발령&quot;이라고 정정했다.</li><li>시민: &quot;대피를 직접 해 보니 실제 전쟁이 났을 때 어떻게 해야 할지 전혀 모르겠다&quot;</li><li>초등학생 학부모: &quot;대피 안내 문자를 받고 나니 학교에 보내도 되는 건지 난감했다&quot;</li><li>대피소 조회 앱(안전디딤돌)이 멈췄고, 네이버 모바일도 6시 43분부터 약 5분간 접속되지 않았다.</li><li>이후 서울시의회에서 경보 문자에 발령 이유, 위치와 시간, 대피 방법을 넣자는 조례 개정안이 나왔다.</li><li>출처 <ul><li>서울신문, &quot;&#39;대피소 도대체 어디 있지?&#39; 새벽 사이렌, 시민들 패닉&quot;, 2023-06-01: <a href="https://m.seoul.co.kr/news/2023/06/01/20230601001006" target="_blank" rel="noreferrer">https://m.seoul.co.kr/news/2023/06/01/20230601001006</a></li><li>이투데이, 네이버 5분간 먹통: <a href="https://www.etoday.co.kr/news/view/2253443" target="_blank" rel="noreferrer">https://www.etoday.co.kr/news/view/2253443</a></li><li>뉴스1, 서울시·행안부 혼선: <a href="https://www.news1.kr/amp/local/seoul/5063192" target="_blank" rel="noreferrer">https://www.news1.kr/amp/local/seoul/5063192</a></li><li>서울신문, 재난문자 손 본다: <a href="https://m.go.seoul.co.kr/news/2023/06/01/20230601500126" target="_blank" rel="noreferrer">https://m.go.seoul.co.kr/news/2023/06/01/20230601500126</a></li></ul></li></ul><hr><h2 id="_5-예비-자료-부모와-떨어진-아이" tabindex="-1">5. 예비 자료: 부모와 떨어진 아이 <a class="header-anchor" href="#_5-예비-자료-부모와-떨어진-아이" aria-label="Permalink to &quot;5. 예비 자료: 부모와 떨어진 아이&quot;">​</a></h2><ul><li><strong>2016년 경주 지진 당일:</strong> 지진 직후 카카오톡이 1~2시간 먹통이었고, 긴급재난문자는 지진 8분 뒤에 왔다. 머니투데이: <a href="https://www.mt.co.kr/society/2016/09/12/2016091222082745009" target="_blank" rel="noreferrer">https://www.mt.co.kr/society/2016/09/12/2016091222082745009</a> , 뉴스핌: <a href="https://newspim.com/news/view/20160912000433" target="_blank" rel="noreferrer">https://newspim.com/news/view/20160912000433</a></li><li><strong>집에 혼자 있던 아이들의 화재 피해:</strong> 최근 4년 화재로 다치거나 숨진 13살 미만 어린이 148명, 숨진 19명은 모두 집에서 난 불. 2025년 부산 기장(8살, 6살 자매), 부산(10살, 7살 자매), 인천(혼자 있던 초등학생). MBC, 2025-07-07: <a href="https://imnews.imbc.com/replay/2025/nwtoday/article/6732871_36807.html" target="_blank" rel="noreferrer">https://imnews.imbc.com/replay/2025/nwtoday/article/6732871_36807.html</a></li></ul>',36)])])}const d=t(i,[["render",o]]);export{c as __pageData,d as default};
